function lockSheet(){const on=!!S.settings.lock;openSheet('Passcode lock',`<p class="muted" style="margin-top:0">Ask for a passcode each time Dash Finance opens. Hub widget amounts are hidden while a lock is set. This is a privacy screen; data on the device is not encrypted.</p>
 ${on?`<div class="fld"><label for="lpOld">Current passcode</label><input id="lpOld" type="password" inputmode="numeric" autocomplete="current-password"></div>`:''}
 <div class="fg"><div class="fld"><label for="lp1">${on?'New passcode (blank to remove)':'New passcode'}</label><input id="lp1" type="password" inputmode="numeric" autocomplete="new-password"></div><div class="fld"><label for="lp2">Confirm</label><input id="lp2" type="password" inputmode="numeric" autocomplete="new-password"></div></div>
 <p class="err" id="lpErr" role="alert"></p><div class="actions"><button class="primary" id="lpGo">${I('lock','sm')} ${on?'Update':'Turn on lock'}</button></div>`,el=>{
 el.querySelector('#lpGo').onclick=async()=>{const e=m=>el.querySelector('#lpErr').textContent=m,p1=el.querySelector('#lp1').value,p2=el.querySelector('#lp2').value;
  if(on){const L=S.settings.lock;if(await hashPw(el.querySelector('#lpOld').value,ub64(L.salt),L.iter)!==L.hash)return e('Current passcode is incorrect.')}
  if(!p1&&on){S.settings.lock=null;await F.save(S);sheet.close();render();return toast('Passcode lock removed')}
  if(p1.length<4)return e('Use at least 4 characters.');if(p1!==p2)return e("Passcodes don't match.");const salt=crypto.getRandomValues(new Uint8Array(16));
  S.settings.lock={salt:b64(salt),iter:210000,hash:await hashPw(p1,salt)};await F.save(S);sheet.close();render();toast('Passcode lock on')}})}
function gate(){if(!S.settings.lock)return Promise.resolve();const g=$('#gate');g.hidden=false;$('#gatePw').value='';setTimeout(()=>$('#gatePw').focus(),50);
 return new Promise(res=>{$('#gateForm').onsubmit=async e=>{e.preventDefault();const L=S.settings.lock;if(await hashPw($('#gatePw').value,ub64(L.salt),L.iter)===L.hash){g.hidden=true;$('#gateErr').textContent='';res()}else{$('#gateErr').textContent='Incorrect passcode.';$('#gatePw').select()}}})}
